<script setup>
import { ref, reactive } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ElMessageBox } from 'element-plus';
import { api } from '../api/index.js';
import { usePolling } from '../components/polling.js';
import StatusTag from '../components/StatusTag.vue';
const route = useRoute(), router = useRouter(), job = ref(null), error = ref(''), busy = ref(false), edits = reactive({});
async function load() { try { job.value = await api(`/workflows/${route.params.id}`, { quiet: true }); for (const i of job.value.items) if (!edits[i.itemId]) edits[i.itemId] = { name: i.identity?.name ?? i.source, year: i.identity?.year ?? undefined }; error.value = ''; } catch (e) { error.value = e.message; } }
const tick = usePolling(load, 3000, () => !job.value || ['queued', 'running'].includes(job.value.status));
async function confirm(item, candidate) { busy.value = true; try { await ElMessageBox.confirm(`将“${item.originalName}”识别为“${candidate.Name}”${candidate.ProductionYear ? `（${candidate.ProductionYear}）` : ''}，并应用到 Jellyfin？`, '确认媒体信息', { confirmButtonText: '确认并应用', cancelButtonText: '取消' }); job.value = await api(`/workflows/${job.value.id}/confirm`, { method: 'POST', body: { itemId: item.itemId, candidateId: candidate.candidateId } }); tick(); } catch {} finally { busy.value = false; } }
async function search(item) { busy.value = true; try { job.value = await api(`/workflows/${job.value.id}/search`, { method: 'POST', body: { itemId: item.itemId, name: edits[item.itemId].name, year: edits[item.itemId].year ?? null } }); tick(); } catch {} finally { busy.value = false; } }
async function retry() { busy.value = true; try { const next = await api(`/workflows/${job.value.id}/retry`, { method: 'POST' }); await router.push(`/jobs/${next.id}`); } catch {} finally { busy.value = false; } }
</script>
<template><div class="toolbar" style="margin-bottom:20px"><el-button @click="router.push('/jobs')">← 返回任务列表</el-button><el-button @click="load">刷新详情</el-button><el-button v-if="job?.status === 'failed' || (job?.status === 'needs_review' && job.items.some(i => i.status === 'failed'))" type="primary" :loading="busy" @click="retry">重试任务</el-button></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="notice" /><section v-if="job" class="panel"><div class="panel-header"><h2>{{ job.input.hash ? '下载完成工作流' : job.input.dryRun ? '媒体候选预览' : '媒体扫描识别' }}</h2><StatusTag :status="job.status" /></div><div class="panel-body"><div class="detail-info"><div><small>任务 ID</small><strong class="path">{{ job.id }}</strong></div><div><small>当前阶段</small><strong>{{ job.stage }}</strong></div><div><small>创建时间</small><strong>{{ new Date(job.createdAt).toLocaleString('zh-CN') }}</strong></div></div><div v-if="job.input.hash" class="path">Torrent: {{ job.input.hash }}</div><el-alert v-if="job.error" :title="job.error" type="error" show-icon :closable="false" /><el-alert v-if="job.message" :title="job.message" type="success" show-icon :closable="false" /><div v-if="['queued', 'running'].includes(job.status)" class="muted">正在自动更新任务进度，请等待当前阶段完成。</div></div></section><section v-if="job?.items.length" class="panel"><div class="panel-header"><h2>媒体处理结果 <span class="muted">{{ job.items.length }} 项</span></h2><span class="muted">自动应用后会回读确认提供方 ID</span></div><article v-for="item in job.items" :key="item.itemId" class="media-result"><div class="result-heading"><div><h3>{{ item.originalName }} <span class="muted">{{ item.type === 'Series' ? '电视剧' : '电影' }}</span></h3><div class="path">{{ item.path }}</div></div><StatusTag :status="item.status" /></div><p class="muted">{{ item.type === 'Series' ? '文件夹' : '文件名' }}：{{ item.source }}<span v-if="item.identity">　→　{{ item.identity.name }}{{ item.identity.year ? ` (${item.identity.year})` : '' }}</span></p><p v-if="item.aiDecision" class="muted">AI 候选判断：{{ item.candidates.find(c => c.candidateId === item.aiDecision.candidateId)?.Name || '未能确定' }}（{{ item.aiDecision.confidence === 'high' ? '高' : '低' }}置信度） · {{ item.aiDecision.reason }}</p><el-alert v-if="item.aiDecisionError" :title="`AI 候选判断未完成：${item.aiDecisionError}`" type="warning" show-icon :closable="false" /><el-alert v-if="item.error" :title="item.error" type="error" show-icon :closable="false" /><div v-if="item.confirmed" class="confirmed">已确认：{{ item.confirmed.Name }} {{ item.confirmed.ProductionYear || '' }}<div class="path" style="margin-top:8px">{{ Object.entries(item.confirmed.ProviderIds || {}).map(([k, v]) => `${k}: ${v}`).join(' · ') }}</div></div><template v-if="item.status === 'needs_review'"><p class="muted">{{ item.message || '选择合适的候选，或修改名称重新搜索。' }}</p><div class="candidate-grid"><div v-for="candidate in item.candidates" :key="candidate.candidateId" class="candidate"><h4>{{ candidate.Name }} <el-tag v-if="item.aiDecision?.confidence === 'high' && item.aiDecision.candidateId === candidate.candidateId" size="small">AI 推荐</el-tag></h4><span class="muted">{{ candidate.ProductionYear || '年份未知' }}</span><p>{{ Object.entries(candidate.ProviderIds || {}).map(([k, v]) => `${k}: ${v}`).join(' · ') }}</p><el-button type="primary" plain :disabled="job.status !== 'needs_review' || busy" @click="confirm(item, candidate)">确认此候选</el-button></div></div><el-empty v-if="!item.candidates.length" description="未找到候选，请尝试调整搜索名称。" :image-size="65" /><div v-if="edits[item.itemId]" class="search-form"><el-input v-model="edits[item.itemId].name" placeholder="媒体名称" aria-label="搜索媒体名称" /><el-input-number v-model="edits[item.itemId].year" :min="1800" :max="new Date().getFullYear() + 5" :controls="false" placeholder="年份（可选）" /><el-button :disabled="job.status !== 'needs_review'" :loading="busy" @click="search(item)">重新搜索</el-button></div></template></article></section></template>
